    parameter int CAM_ENTRIES = 1024,
    parameter int HIDDEN = 96,
    parameter int ADDR_W = 21,
    parameter int ROW_W = (CAM_ENTRIES < 2) ? 1 : $clog2(CAM_ENTRIES),
