                    edge_limit > 32'd131072 || path_limit == '0 || path_limit > 32'(BOARD_SIZE*BOARD_SIZE+1) ||
                    exploration_constant[63] || exploration_constant > 64'h4020000000000000) begin
                    error_d = 8'h01;
                    phase_d = ST_RESULT;
                end
            end
